<?php
namespace App\Services;
use App\Models\IkontrolInstance; use Illuminate\Support\Facades\DB; use Throwable;
class IkontrolInstanceConnectionService { public function test(IkontrolInstance $i):array{$name='instance_'.$i->id;config(["database.connections.$name"=>['driver'=>'mysql','host'=>config('ikontrol.db.host'),'port'=>config('ikontrol.db.port'),'database'=>$i->db_name,'username'=>config('ikontrol.db.username'),'password'=>config('ikontrol.db.password'),'charset'=>'utf8mb4','collation'=>'utf8mb4_unicode_ci','prefix'=>'','strict'=>true]]);$start=microtime(true);try{DB::purge($name);DB::connection($name)->select('SELECT 1');$r=['success'=>true,'message'=>'Conexion correcta.','response_time_ms'=>(int)((microtime(true)-$start)*1000)];}catch(Throwable){$r=['success'=>false,'message'=>'No fue posible conectar con la base de datos.','response_time_ms'=>(int)((microtime(true)-$start)*1000)];}finally{DB::disconnect($name);}$i->update(['last_connection_at'=>now(),'last_connection_status'=>$r['success']?'CONNECTED':'ERROR','last_connection_error'=>$r['success']?null:$r['message']]);return $r;} }
